grep '^cpu[0-2] ' /proc/stat; ( /tmp/rt-audit-tools/rtload cpu 0 60 > /tmp/rt-audit-run/CPU-load0.txt 2>&1 & l0=$!; /tmp/rt-audit-tools/rtload cpu 2 60 > /tmp/rt-audit-run/CPU-load2.txt 2>&1 & l2=$!; echo "$l0 $l2" > /tmp/rt-audit-run/CPU-load.pids; /tmp/rt-audit-tools/cyclictest --laptop -a1 -t1 -p80 --policy=fifo -m -i1000 -D60 -q -h2000 > /tmp/rt-audit-run/CPU.txt 2>&1; c=$?; wait "$l0"; a=$?; wait "$l2"; b=$?; printf '%s %s %s\n' "$c" "$a" "$b" > /tmp/rt-audit-run/CPU.rc ) & echo "CPU_WRAPPER_PID=$!"; cat /proc/uptime
